package com.eccraft.npc;

import net.minecraft.network.syncher.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.util.Mth;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.storage.*;import java.util.UUID;

public final class NpcNormalEntity extends PathfinderMob{
 private static final EntityDataAccessor<String> DEFINITION=SynchedEntityData.defineId(NpcNormalEntity.class,EntityDataSerializers.STRING),MODEL_TYPE=SynchedEntityData.defineId(NpcNormalEntity.class,EntityDataSerializers.STRING),MODEL=SynchedEntityData.defineId(NpcNormalEntity.class,EntityDataSerializers.STRING),TEXTURE=SynchedEntityData.defineId(NpcNormalEntity.class,EntityDataSerializers.STRING),IDLE=SynchedEntityData.defineId(NpcNormalEntity.class,EntityDataSerializers.STRING),PLAYER_NAME=SynchedEntityData.defineId(NpcNormalEntity.class,EntityDataSerializers.STRING),DISPLAY=SynchedEntityData.defineId(NpcNormalEntity.class,EntityDataSerializers.STRING);private static final EntityDataAccessor<Float>SCALE=SynchedEntityData.defineId(NpcNormalEntity.class,EntityDataSerializers.FLOAT);
 private UUID talking;private long lockUntil;private float targetYaw,targetPitch;private int turnTicks;
 public NpcNormalEntity(EntityType<? extends NpcNormalEntity> type,Level level){super(type,level);setNoGravity(true);setNoAi(true);setPersistenceRequired();}
 public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,10).add(Attributes.MOVEMENT_SPEED,0);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(DEFINITION,"eccraft:test_npc");b.define(MODEL_TYPE,"gltf");b.define(MODEL,"");b.define(TEXTURE,"");b.define(IDLE,"");b.define(PLAYER_NAME,"");b.define(DISPLAY,"NPC");b.define(SCALE,0.1F);}
 public String definition(){return entityData.get(DEFINITION);}public String modelType(){return entityData.get(MODEL_TYPE);}public String model(){return entityData.get(MODEL);}public String texture(){return entityData.get(TEXTURE);}public String idle(){return entityData.get(IDLE);}public String playerName(){return entityData.get(PLAYER_NAME);}public String display(){return entityData.get(DISPLAY);}public float modelScale(){return entityData.get(SCALE);}
 private void applyDefinition(){var d=NpcRegistry.INSTANCE.definitions.get(definition());if(d!=null){entityData.set(MODEL_TYPE,d.modelType());entityData.set(MODEL,d.model());entityData.set(TEXTURE,d.texture());entityData.set(IDLE,d.idle());entityData.set(PLAYER_NAME,d.playerName());entityData.set(DISPLAY,d.name());entityData.set(SCALE,d.scale());setCustomName(net.minecraft.network.chat.Component.literal(d.name()));setCustomNameVisible(true);}}
 @Override public void tick(){super.tick();setDeltaMovement(0,0,0);if(!level().isClientSide()&&tickCount%20==1)applyDefinition();if(turnTicks>0){setYRot(Mth.rotLerp(0.25F,getYRot(),targetYaw));setXRot(Mth.lerp(0.25F,getXRot(),targetPitch));yBodyRot=getYRot();yHeadRot=getYRot();turnTicks--;}if(!level().isClientSide()&&talking!=null&&(level().getGameTime()>lockUntil||level().getPlayerByUUID(talking)==null||distanceToSqr(level().getPlayerByUUID(talking))>64))release(talking);}
 @Override protected InteractionResult mobInteract(Player player,InteractionHand hand){if(hand!=InteractionHand.MAIN_HAND)return InteractionResult.PASS;if(level().isClientSide())return InteractionResult.SUCCESS;if(!(player instanceof ServerPlayer sp))return InteractionResult.PASS;if(talking!=null&&!talking.equals(player.getUUID())){sp.sendSystemMessage(net.minecraft.network.chat.Component.literal("该角色正在与其他玩家交谈。"));return InteractionResult.CONSUME;}talking=player.getUUID();lockUntil=level().getGameTime()+600;double dx=player.getX()-getX(),dz=player.getZ()-getZ(),dy=player.getEyeY()-getEyeY();targetYaw=(float)(Mth.atan2(dz,dx)*180/Math.PI)-90;targetPitch=(float)(-(Mth.atan2(dy,Math.sqrt(dx*dx+dz*dz))*180/Math.PI));turnTicks=8;NpcDialogueManager.open(sp,this,null);return InteractionResult.CONSUME;}
 public boolean isTalkingTo(ServerPlayer p){return talking!=null&&talking.equals(p.getUUID())&&distanceToSqr(p)<=64;}public void refreshLock(){lockUntil=level().getGameTime()+600;}public void release(UUID id){if(talking!=null&&talking.equals(id))talking=null;}
 // NPCs must remain present regardless of distance or inactivity.
 @Override public boolean removeWhenFarAway(double distanceSquared){return false;}
 @Override public boolean requiresCustomPersistence(){return true;}
 @Override public boolean isPushable(){return false;}@Override public void push(Entity e){}@Override protected boolean canRide(Entity e){return false;}
 @Override protected void addAdditionalSaveData(ValueOutput out){super.addAdditionalSaveData(out);out.putString("NpcDefinition",definition());}
 @Override protected void readAdditionalSaveData(ValueInput in){super.readAdditionalSaveData(in);setPersistenceRequired();setNoGravity(true);setNoAi(true);entityData.set(DEFINITION,in.getStringOr("NpcDefinition","eccraft:test_npc"));applyDefinition();}
}
